#include <stdio.h>

/* ── 两处都抄了同一行宣告 ── */
int add(int a, int b);
int add(int a, int b);

int main(void) {
    printf("结果 %d\n", add({a}, {b}));
    return 0;
}

/* ── 身子：只留一份，别人抄不走它 ── */
int add(int a, int b) {
    return a + b;
}
